fn solve(n: i8, m: i8) -> i8 {
    // First, form as many mixed groups as possible.
    // Each mixed group uses 1 unit of the first resource and 2 of the second.
    let mixed = n.min(m / 2);

    // Subtract the second‐resource units consumed by the mixed groups.
    let remaining_second = m - mixed * 2;

    // Then form pure groups from the remaining second resource.
    // Each pure group uses 4 units of the second resource.
    let pure = remaining_second / 4;

    // Total groups is the sum of mixed and pure groups.
    mixed + pure
}

